findings.codeql_raw_query:
/**
 * @name User-controlled regex compilation
 * @description Detecting if user input flows into regex compilation which might lead to ReDoS
 * @kind path-problem
 * @problem.severity warning
 * @id py/user-controlled-regex
 * @tags security
 *       external/cwe/cwe-1333
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module RegexConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    sink = API::moduleImport("re").getMember("compile").getACall().getArg(0)
  }
}

module RegexFlow = TaintTracking::Global<RegexConfig>;
import RegexFlow::PathGraph

from RegexFlow::PathNode source, RegexFlow::PathNode sink
where RegexFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Regex compilation from $@.", source.getNode(), "parameter"
